#include <iostream>
#include <cstdio>
#include <cstdlib>
#include <algorithm>
#include <memory.h>
#include <cmath>
#include <vector>
#include <string>
#include <queue>
#include <deque>

using namespace std;

const double eps = 0.000000001;
long long x1, x2, ansy1, ansy2;
double t1, t2, t0, ans;

double pr(long long y1, long long y2) {
    return (t1 * y1 + t2 * y2) / (y1 + y2);
}

int main() {
    long long y1, y2;

    cin >> t1 >> t2 >> x1 >> x2 >> t0;

    if (t1 == t2) {
        cout << x1 << " " << x2 << endl;
        return 0;
    }

    if (t1 == t0 || t2 == t0) {
        if (t1 == t0)
            cout << x1 << " 0" << endl;
        else
            cout << "0 " << x2 << endl;
        return 0;
    }

    ansy1 = ansy2 = 0;
    ans = 1e18;

    for (y1 = 0; y1 <= x1; ++y1) {
        y2 = static_cast<long long>((t0 - t1) * y1 / (t2 - t0));

        while (y1 + y2 > 0 && pr(y1, y2) < t0)
            ++y2;

        if (y1 + y2 == 0 || y2 < 0 || y2 > x2)
            continue;

        double current = pr(y1, y2);
        if (current < ans ||
            (abs(ans - current) < eps &&
             ansy1 + ansy2 < y1 + y2)) {
            ans = current;
            ansy1 = y1;
            ansy2 = y2;
        }
    }

    cout << ansy1 << " " << ansy2 << endl;
    return 0;
}

